class Solution:
    def totalFruit(self, fruits: list[int]) -> int:
        count = defaultdict(int)
        l = 0
        ans = 0

        for r in range(len(fruits)):
            # invalid state -> shrink and get new fruit:
            while len(count) == 2 and fruits[r] not in count:
                count[fruits[l]] -= 1
                if count[fruits[l]] <= 0:
                    count.pop(fruits[l])
                l += 1

            count[fruits[r]] += 1
            ans = max(ans, r - l + 1)

        return ans
